  const segmentPath=points=>{let path='',open=false;points.forEach((point,index)=>{if(!isNumber(point.value)){open=false;return;}path+=`${open?'L':'M'}${x(index).toFixed(1)},${y(point.value).toFixed(1)} `;open=true;});return path;};
