  cards([['在榜项目',num(all.length),`${labels[period]} · GitHub 全站`],['最高新增 Stars',all.length?num(Math.max(...all.map(row=>Number(row.new_stars)||0))):'—',`GitHub ${labels[period]}口径`],['明显增量',num(hot.size),'正值排名前 20%']]);
  $('#chart').innerHTML='';
