function githubDescription(row){const translated=row.use_case_translation_status==='machine'?(row.use_case_zh||'').split('；简介：')[1]:'';return translated||row.description_raw||row.readme_excerpt||'暂无可核实简介';}
function renderGithub(p){const rows=filterRows(p.rows,['full_name','domain','description_raw','readme_excerpt','use_case_zh'],'domain');const hot=topGrowthIds(p.rows,'stars_net_change','full_name');renderFilters(p.rows,'domain');$('#filters').insertAdjacentHTML('afterbegin',githubViewNav());bindGithubView();cards([['AI 项目',num(p.rows.length),'Trending、Topic 与官方仓库'],['Stars 净变化',num(p.rows.reduce((sum,r)=>sum+(r.stars_net_change||0),0)),'与上次成功快照比较'],['最新 Release',num(p.rows.filter(r=>r.latest_release).length),'来自官方仓库 API']]);$('#chart').innerHTML='';$('#content').innerHTML=table(['项目','领域','来源','总 Stars','净变化','用途'],rows.map(r=>[link(r.url,r.full_name),esc(r.domain),esc(r.source_type||'trending'),num(r.stars),growthCell(r.stars_net_change,hot.has(r.full_name)),esc(githubDescription(r))])).replace('<table>','<table class="project-table">');}

function usdBillions(value){return isNumber(value)?'$'+(Number(value)/1e9).toLocaleString('zh-CN',{maximumFractionDigits:2})+'B':'—';}
function metricPeriod(metric){return metric?`${esc(metric.period_start||'—')} → ${esc(metric.period_end||'—')}`:'—';}
function sourceHealth(p){return `<div class="source-health">来源状态：${(p.sources||[]).map(s=>`<span class="source-${esc(s.status)}" title="${esc(s.error||'')}">${esc(s.name)} <b>${esc(s.status)}</b></span>`).join('')}</div>`;}
const finPeriods=['FY','TTM','Quarter','YTD'];
const finMetrics=[
  ['capex','资本开支 CapEx','usd',false],['revenue','营收 Revenue','usd',false],['operating_cash_flow','经营现金流 OCF','usd',false],
  ['revenue_yoy','营收同比 Revenue YoY','pct',true],['capex_yoy','资本开支同比 CapEx YoY','pct',true],
  ['capex_to_revenue','CapEx / Revenue','pct',true],['capex_to_ocf','CapEx / OCF','pct',true],
  ['free_cash_flow','自由现金流 FCF','usd',true],['free_cash_flow_margin','FCF Margin','pct',true],
  ['operating_income','营业利润 Operating Income','usd',false],['operating_margin','Operating Margin','pct',true]
];
function finSnapshot(row){const period=row.periods?.[state.finPeriod];return period?{...period,metrics:period.metrics||{},legacy:false}:(row.periods?{label:state.finPeriod,metrics:{},status:'unavailable',missing_reason:'此期间尚无可靠数据',legacy:false}:{label:'旧版混合期间',metrics:state.finPeriod==='FY'?(row.metrics||{}):{},status:'unavailable',missing_reason:'旧版快照未提供统一期间数据',legacy:true});}
function finMetric(row,key){return finSnapshot(row).metrics[key]||null;}
function finUsable(metric,kind){return metric&&metric.status!=='missing'&&metric.status!=='unavailable'&&isNumber(kind==='pct'?metric.value_pct:metric.value_usd);}
function finValue(metric,kind,key=''){if(!finUsable(metric,kind))return key==='capex_to_ocf'&&/(?:OCF|经营现金流).*(?:负|negative)|(?:负|negative).*(?:OCF|经营现金流)|N\/M/i.test(metric?.missing_reason||'')?'N/M':'N/A';return kind==='pct'?`${num(metric.value_pct)}%`:usdBillions(metric.value_usd);}
function finUrl(url){try{const parsed=new URL(url);return parsed.protocol==='https:'&&['www.sec.gov','sec.gov'].includes(parsed.hostname)?parsed.href:'';}catch{return '';}}
function finLink(url,label){return link(finUrl(url),label);}
function finReason(metric,period,key,row){if(metric?.missing_reason)return metric.missing_reason;if(period.legacy){const old=row.omitted_metrics?.find(item=>item.metric===key);if(old?.reason)return old.reason;}if(period.missing_reason)return period.missing_reason;return metric?.status==='unavailable'?'来源当前不可用':'未取得可靠披露或可比期间';}
function finMetricDetail(row,period,[key,label,kind,derived]){
  const metric=period.metrics[key],usable=finUsable(metric,kind),reason=usable?'':finReason(metric,period,key,row);
  const source=metric?.filing_url?finLink(metric.filing_url,`${metric.form||'文件'} · ${metric.filing_date||'申报日未知'}`):'暂无原件链接';
  const inputNames={capex:'CapEx',revenue:'Revenue',operating_cash_flow:'OCF',operating_income:'Operating Income',prior:'上年同期'};
  const inputs=metric?.inputs&&typeof metric.inputs==='object'?Object.entries(metric.inputs).map(([name,input])=>{if(!input||typeof input!=='object')return '';const value=isNumber(input.value_usd)?usdBillions(input.value_usd):isNumber(input.value_pct)?`${num(input.value_pct)}%`:'N/A';return `<span>${esc(inputNames[name]||name)} ${value} · ${metricPeriod(input)}${input.filing_url?` · ${finLink(input.filing_url,'原件')}`:''}</span>`;}).filter(Boolean).join(''):'';
  return `<div class="fin-metric"><div class="fin-metric-top"><strong>${esc(label)}</strong><span class="fin-kind ${derived?'derived':'reported'}">${derived?'Derived':'Reported'}</span></div><b class="fin-metric-value">${esc(finValue(metric,kind,key))}</b><small>期间：${metricPeriod(metric)}</small><small>状态：${esc(usable?'可用':metric?.status||period.status||'missing')}${reason?` · ${esc(reason)}`:''}</small><small>来源：${source}</small>${metric?.concept?`<small>标签：${esc(metric.concept)}</small>`:''}${metric?.formula?`<small>公式：${esc(metric.formula)}</small>`:''}${inputs?`<div class="fin-inputs"><span>计算依据</span>${inputs}</div>`:''}</div>`;
}
function finDetail(row,period){return `<div class="fin-detail-head"><div><strong>${esc(row.company||row.ticker)} · ${esc(row.ticker)}</strong><small>${esc(row.sector_group||'未分类')} · ${esc(row.reporting_standard||'准则未标注')} · ${esc(period.label||state.finPeriod)} · ${esc(period.period_start||'—')} → ${esc(period.period_end||'—')}</small></div><span class="status ${esc(period.status||row.status||'unavailable')}">${esc(period.status||row.status||'unavailable')}</span></div>${period.legacy?'<div class="notice warning">旧版快照未按统一期间建模；仅展示各项原始披露，跨项目比率不可比较。</div>':''}<div class="fin-detail-grid">${finMetrics.map(item=>finMetricDetail(row,period,item)).join('')}</div>`;}
function finFilterControls(rows){
  const groups=[...new Set(rows.map(row=>row.sector_group||'未分类'))].sort();
  $('#filters').innerHTML=`<label><span class="sr-only">搜索公司或代码</span><input id="search" type="search" value="${esc(state.query)}" placeholder="搜索公司或代码"></label><label><span class="sr-only">产业链分组</span><select id="fin-group" aria-label="产业链分组"><option value="all">全部产业链</option>${groups.map(group=>`<option value="${esc(group)}" ${state.finGroup===group?'selected':''}>${esc(group)}</option>`).join('')}</select></label><label><span class="sr-only">财务期间</span><select id="fin-period" aria-label="财务期间">${finPeriods.map(period=>`<option value="${period}" ${state.finPeriod===period?'selected':''}>${period}</option>`).join('')}</select></label><label><span class="sr-only">财务排序</span><select id="fin-sort" aria-label="财务排序"><option value="default">原始公司顺序</option><option value="capex_yoy" ${state.finSort==='capex_yoy'?'selected':''}>CapEx YoY ↓</option><option value="capex_to_revenue" ${state.finSort==='capex_to_revenue'?'selected':''}>CapEx / Revenue ↓</option><option value="free_cash_flow" ${state.finSort==='free_cash_flow'?'selected':''}>FCF ↓</option></select></label>`;
  $('#search').oninput=event=>{state.query=event.target.value;updateUrl();renderCurrent();$('#search')?.focus();$('#search')?.setSelectionRange(state.query.length,state.query.length);};
  $('#fin-group').onchange=event=>{state.finGroup=event.target.value;renderCurrent();};
  $('#fin-period').onchange=event=>{state.finPeriod=event.target.value;state.finExpanded=null;renderCurrent();};
  $('#fin-sort').onchange=event=>{state.finSort=event.target.value;renderCurrent();};
}
function renderAiFinancials(p){
  const all=p.rows||[],legacy=all.some(row=>!row.periods),withCapex=all.filter(row=>finUsable(finMetric(row,'capex'),'usd'));
  const latest=all.flatMap(row=>Object.values(finSnapshot(row).metrics||{}).filter(Boolean)).map(metric=>metric.filing_date).filter(Boolean).sort().at(-1);
  const q=state.query.trim().toLowerCase(),rows=all.filter(row=>(!q||`${row.company||''} ${row.ticker||''}`.toLowerCase().includes(q))&&(state.finGroup==='all'||(row.sector_group||'未分类')===state.finGroup));
  if(state.finSort!=='default'){const kind=state.finSort==='free_cash_flow'?'usd':'pct';rows.sort((a,b)=>{const av=finMetric(a,state.finSort),bv=finMetric(b,state.finSort),an=finUsable(av,kind)?Number(kind==='usd'?av.value_usd:av.value_pct):null,bn=finUsable(bv,kind)?Number(kind==='usd'?bv.value_usd:bv.value_pct):null;return an===null&&bn===null?0:an===null?1:bn===null?-1:bn-an;});}
  finFilterControls(all);
  cards([['观察公司',num(all.length),legacy?'旧版快照期间未统一':'统一公司池；财年结束日可能不同'],['CapEx 可用覆盖',`${num(withCapex.length)}/${num(all.length)}`,`${state.finPeriod} · 全公司现金支出`],['最新申报日',latest||'—','申报日期 ≠ 财务期间结束日']]);
  $('#chart').innerHTML=`<div class="notice">资本开支为全公司现金流量表中购建物业、厂房及设备支出，不等于 AI 专项投资。当前选择 ${esc(state.finPeriod)}；各指标的起止日期与原件在公司详情中逐项标明。</div>${legacy?'<div class="notice warning">部分公司仍使用旧版快照，期间尚未统一；这些行只展示原始事实，派生指标显示 N/A。</div>':''}${sourceHealth(p)}`;
  $('#content').innerHTML=rows.length?`<p class="fin-scroll-hint">主表可横向滚动；展开公司查看全部 11 项指标、缺失原因及计算依据。</p><div class="table-wrap fin-table-wrap"><table class="fin-table"><thead><tr>${['公司','资本开支 · USD B','CapEx Period','营收 · USD B','经营现金流 · USD B','CapEx / Revenue','FCF · USD B','申报日 / 原件'].map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>{const period=finSnapshot(row),m=period.metrics,capex=m.capex,revenue=m.revenue,ocf=m.operating_cash_flow,ratio=m.capex_to_revenue,fcf=m.free_cash_flow,filing=[capex,revenue,ocf].find(item=>item?.filing_date),open=state.finExpanded===row.ticker;return `<tr class="fin-company-row"><td><button class="fin-expand" data-fin-expand="${esc(row.ticker)}" aria-expanded="${open}" aria-controls="fin-detail-${esc(row.ticker)}">${open?'▾':'▸'} ${esc(row.company||row.ticker)} · ${esc(row.ticker)}</button><small class="ai-metric-period">${esc(row.sector_group||'未分类')}</small>${row.company_url?`<small class="ai-metric-period">${finLink(row.company_url,'公司 SEC 档案')}</small>`:''}</td><td>${esc(finValue(capex,'usd'))}<small class="ai-metric-period">${esc(finUsable(capex,'usd')?'Reported':finReason(capex,period,'capex',row))}</small></td><td>${metricPeriod(capex)}</td><td>${esc(finValue(revenue,'usd'))}<small class="ai-metric-period">${metricPeriod(revenue)}</small></td><td>${esc(finValue(ocf,'usd'))}<small class="ai-metric-period">${metricPeriod(ocf)}</small></td><td>${esc(finValue(ratio,'pct','capex_to_revenue'))}<small class="ai-metric-period">${finUsable(ratio,'pct')?'Derived':'N/A'}</small></td><td>${esc(finValue(fcf,'usd'))}<small class="ai-metric-period">${finUsable(fcf,'usd')?'Derived':'N/A'}</small></td><td>${filing?finLink(filing.filing_url,`${filing.filing_date||'—'} · ${filing.form||'—'}`):'N/A'}</td></tr><tr class="fin-detail-row" id="fin-detail-${esc(row.ticker)}" ${open?'':'hidden'}><td colspan="8">${finDetail(row,period)}</td></tr>`;}).join('')}</tbody></table></div>`:'<div class="empty">当前搜索与产业链分组中没有公司。</div>';
  document.querySelectorAll('[data-fin-expand]').forEach(button=>button.onclick=()=>{const row=rows.find(item=>item.ticker===button.dataset.finExpand);if(!row)return;if(window.matchMedia('(max-width: 700px)').matches){$('#drawer-title').textContent=`${row.company||row.ticker} · ${row.ticker}`;$('#drawer-content').innerHTML=finDetail(row,finSnapshot(row));$('#drawer').showModal();return;}state.finExpanded=state.finExpanded===button.dataset.finExpand?null:button.dataset.finExpand;renderCurrent();document.querySelector('[data-fin-expand="'+CSS.escape(button.dataset.finExpand)+'"]')?.focus();});
}
function renderAiFrontier(p){
  const rows=filterRows(p.rows,['benchmark','dimension','model_id','title','summary_raw'],'dimension'),benchmarks=rows.filter(r=>r.kind==='benchmark'),papers=rows.filter(r=>r.kind==='paper');
  renderFilters(p.rows,'dimension');
  cards([['基准结果',num(p.rows.filter(r=>r.kind==='benchmark').length),'不同基准分数不可混算'],['独立验证',num(p.rows.filter(r=>r.kind==='benchmark'&&r.verified).length),'未验证结果单独标注'],['论文条目',num(p.rows.filter(r=>r.kind==='paper').length),'保留原文与实际发布时间']]);
  $('#chart').innerHTML=`<div class="notice">榜单仅展示官方接口所收录的结果，不代表全部模型；无结果发布日期时仅记录采集时间 ${esc(p.collected_at_utc||'未知')}，不宣称当日发布。</div>${sourceHealth(p)}`;
  const scores=benchmarks.length?table(['基准','名次','较前次','模型','原始分','验证','来源'],benchmarks.map(r=>[link(r.benchmark_url,r.benchmark),num(r.rank),r.rank_change===null||r.rank_change===undefined?'—':`${r.rank_change>0?'+':''}${num(r.rank_change)}`,link(r.url,r.model_id),num(r.score),r.verified?'已验证':'未独立验证',link(r.source_url,r.source_type||'模型卡')])):'<div class="empty">当前筛选没有榜单结果。</div>';
  const paperCards=papers.length?`<div class="news-grid">${papers.map(r=>`<article class="news"><div class="meta"><span class="tag">研究论文</span><time>${esc(r.published_at_utc?.slice(0,10)||'发布时间未知')}</time></div><h3>${link(r.url,r.title)}</h3><p>${esc((r.summary_raw||'原文摘要未提供').slice(0,300))}</p><small>原文 · ${link(r.arxiv_url,r.paper_id)} · HF 提交 ${esc(r.submitted_at_utc?.slice(0,10)||'未知')}</small></article>`).join('')}</div>`:'<div class="empty">当前筛选没有论文。</div>';
  $('#content').innerHTML=`<div class="result-head"><div><b>模型能力基准</b><small>各基准独立排序；原始分不跨基准比较。</small></div></div>${scores}<div class="result-head"><div><b>研究论文</b><small>Hugging Face Daily Papers 的原文条目。</small></div></div>${paperCards}`;
}

function xDate(value){const date=new Date(value);return Number.isNaN(date.getTime())?'时间未知':date.toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});}
function xUrl(value){return /^https:\/\/x\.com\/[A-Za-z0-9_]+\/status\/\d+$/.test(value||'')?value:'';}
function positionXMenus(picker=$('#x-category-picker')){
  if(!picker||window.matchMedia('(max-width: 700px)').matches)return;
  const panel=picker.querySelector('.x-category-panel');
  if(!panel)return;
  const edge=8;
  picker.classList.remove('opens-left');
  const pickerRect=picker.getBoundingClientRect();
  const panelWidth=panel.getBoundingClientRect().width||Math.max(278,panel.scrollWidth);
  if(pickerRect.left+panelWidth>window.innerWidth-edge&&pickerRect.right-panelWidth>=edge)picker.classList.add('opens-left');
  picker.querySelectorAll('.x-category-entry').forEach(entry=>{
    const submenu=entry.querySelector('.x-account-submenu');
    const rect=entry.getBoundingClientRect();
    const measuredWidth=submenu.getBoundingClientRect().width;
    const submenuWidth=measuredWidth||360;
    const roomRight=window.innerWidth-rect.right-edge;
    const roomLeft=rect.left-edge;
    const opensLeft=roomRight<submenuWidth&&roomLeft>roomRight;
    entry.classList.toggle('opens-left',opensLeft);
    const available=Math.max(180,Math.min(360,opensLeft?roomLeft:roomRight));
    submenu.style.setProperty('--x-submenu-max-width',`${available}px`);
  });
}
window.addEventListener('resize',()=>{if(state.module==='x-watch')positionXMenus();},{passive:true});
function renderXWatch(p){
  const accounts=p.accounts||[];const categories=[...new Set(accounts.map(account=>account.category))];
  const returnedHandles=new Set(p.rows.map(row=>String(row.handle).toLowerCase()));
  const failedHandles=new Set((p.failed_accounts||[]).map(handle=>String(handle).toLowerCase()));
  const currentAccount=accounts.find(account=>account.handle.toLowerCase()===state.xAccount);
  const selection=state.xAccount!=='all'?`${currentAccount?.category||state.xCategory} › ${currentAccount?.name||state.xAccount}`:state.xCategory==='all'?'全部分类':state.xCategory;
  const picker=`<div class="x-category-picker" id="x-category-picker"><button class="x-category-trigger" type="button" aria-haspopup="true">${esc(selection)} <span aria-hidden="true">⌄</span></button><div class="x-category-panel" role="menu"><button type="button" class="x-all-categories" data-x-all role="menuitem">全部分类</button>${categories.map(category=>{const children=accounts.filter(account=>account.category===category);return `<div class="x-category-entry"><button type="button" class="x-category-option" data-x-category="${esc(category)}" aria-haspopup="true" role="menuitem">${esc(category)} <span aria-hidden="true">›</span></button><div class="x-account-submenu" role="menu" aria-label="${esc(category)}账号"><button type="button" data-x-account="all" data-x-account-category="${esc(category)}" role="menuitem">全部账号</button>${children.map(account=>{const handle=account.handle.toLowerCase();const note=failedHandles.has(handle)?' · 查询失败':returnedHandles.has(handle)?'':' · 本期无动态';return `<button type="button" data-x-account="${esc(account.handle)}" data-x-account-category="${esc(category)}" role="menuitem">${esc(account.name)} <small>@${esc(account.handle)}${note}</small></button>`}).join('')}</div></div>`}).join('')}</div></div>`;
  const extras=`${picker}<label><span class="sr-only">优先关注筛选</span><select id="x-scope" aria-label="优先关注筛选"><option value="all">全部 50 个账号</option><option value="priority" ${state.xPriority?'selected':''}>优先关注 15 个</option></select></label>`;
  renderFilters(p.rows,'',extras);
  const categoryPicker=$('#x-category-picker');
  categoryPicker?.addEventListener('pointerover',event=>{const entry=event.target.closest('.x-category-entry');if(entry)positionXMenus(categoryPicker);});
  categoryPicker?.addEventListener('focusin',()=>positionXMenus(categoryPicker));
  requestAnimationFrame(()=>positionXMenus(categoryPicker));
  $('#x-scope')?.addEventListener('change',event=>{state.xPriority=event.target.value==='priority';state.xAccount='all';state.xCategory='all';renderCurrent();});
  $('#x-category-picker')?.querySelector('[data-x-all]')?.addEventListener('click',()=>{state.xCategory='all';state.xAccount='all';renderCurrent();});
  $('#x-category-picker')?.querySelectorAll('[data-x-category]').forEach(button=>button.addEventListener('click',()=>{const entry=button.closest('.x-category-entry');entry.classList.toggle('is-open');}));
  $('#x-category-picker')?.querySelectorAll('[data-x-account]')?.forEach(button=>button.addEventListener('click',()=>{state.xCategory=button.dataset.xAccountCategory;state.xAccount=button.dataset.xAccount.toLowerCase();state.xPriority=false;renderCurrent();}));
  let rows=filterRows(p.rows,['text','handle','account_name','focus','category']);
  if(state.xCategory!=='all')rows=rows.filter(row=>row.category===state.xCategory);
  if(state.xAccount!=='all')rows=rows.filter(row=>row.handle.toLowerCase()===state.xAccount);
  if(state.xPriority)rows=rows.filter(row=>row.priority);
  const returned=p.returned_accounts_count??new Set(p.rows.map(row=>String(row.handle).toLowerCase())).size;
  const noActivity=(p.no_activity_accounts||[]).length;const failed=(p.failed_accounts||[]).length;
  const noActivityNote=`${noActivity} 个账号近7天未发布${failed?` · ${failed} 个账号查询失败`:''}`;
  cards([['本期动态',num(p.rows.length),`最近 ${num(p.days||7)} 天`],['返回账号',`${num(returned)}/${num(p.accounts_count||50)}`,noActivityNote],['优先账号',num(p.priority_accounts_count||15),'来自上传清单的精选子集']]);
  $('#chart').innerHTML='';
  if(!rows.length&&state.xAccount!=='all'&&(!returnedHandles.has(state.xAccount)||state.query)){
    const account=currentAccount;const message=failedHandles.has(state.xAccount)?'查询失败，暂不能判断本期动态':state.query?'没有符合搜索条件的动态':'本期无动态';$('#content').innerHTML=`<div class="x-grid"><article class="x-post x-no-activity"><div class="x-head"><div><strong>${esc(account?.name||state.xAccount)}</strong><span>@${esc(account?.handle||state.xAccount)}</span></div></div><p class="x-no-activity-label">${esc(message)}</p></article></div>`;
  }else{$('#content').innerHTML=rows.length?`<div class="x-grid">${rows.map(row=>{const url=xUrl(row.url);return `<article class="x-post"><div class="x-head"><div><strong>${esc(row.account_name||row.handle)}</strong><span>@${esc(row.handle)} · ${esc(xDate(row.published_at))}</span></div>${row.priority?'<span class="tag">优先关注</span>':''}</div><p class="x-focus">${esc(row.focus||'')}</p><p class="x-text">${esc(row.text)}</p><div class="x-foot"><span>${row.likes==null?'点赞 —':'点赞 '+num(row.likes)} · ${row.views==null?'浏览 —':'浏览 '+num(row.views)} · ${row.oembed_status==='ok'?'oEmbed 已复核':'Chrome 页面正文'}</span>${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">查看 X 原文 ↗</a>`:''}</div></article>`}).join('')}</div>`:'<div class="empty">没有符合搜索条件的动态。</div>';}
  $('#method').textContent=(p.methodology||'')+` 清单 ${p.accounts_count||50} 个账号，本轮成功查询 ${(p.checked_accounts||[]).length} 个${failed?`，失败 ${failed} 个`:''}；采集完成时间 ${p.finished_at?xDate(p.finished_at):'—'}。`;
}

function renderPayload(name,p){if(name==='token')renderToken(p);else if(name==='models')renderModels(p);else if(name==='gpu')renderGpuRefined(p);else if(name==='storage')renderStorage(p);else if(name==='hugging-face')renderHf(p);else if(name==='github-trending')renderTrending(p);else if(name==='github')renderGithub(p);else if(name==='ai-financials')renderAiFinancials(p);else if(name==='ai-frontier')renderAiFrontier(p);else if(name==='x-watch')renderXWatch(p);if(name!=='x-watch')$('#method').textContent=(p.methodology||'')+(['github-trending','github','hugging-face'].includes(name)?' 红字表示该榜单正增量排名前 20%。':'');}
async function renderCurrent(){const name=state.module,info=modules[name];const dataName=name==='github'&&state.githubView==='trending'?'github-trending':name;$('#title').textContent=info.title;$('#subtitle').textContent=info.subtitle;$('#panel-title').textContent=name==='overview'?'数据源与板块':'数据与图表';$('#date').textContent=state.manifest?.snapshot_date||'读取中';document.querySelectorAll('[data-module]').forEach(button=>button.classList.toggle('active',button.dataset.module===name));const status=moduleStatus(dataName);setStatus(isStale(status)?`本板块状态：${status.status}。${status.error||'部分来源不可用，当前展示最近可用数据。'}`:'',isStale(status)?'warning':'');if(name==='overview'){renderOverview();return;}$('#chart').innerHTML='<div class="loading">读取模块数据…</div>';$('#content').innerHTML='';try{const payload=await loadModule(dataName);if(state.module!==name)return;renderPayload(dataName,payload);}catch(error){if(state.module!==name)return;$('#filters').innerHTML='';$('#chart').innerHTML='';$('#content').innerHTML=`<div class="empty">${esc(error.message)}。该板块尚无可发布快照。</div>`;$('#method').textContent='';}}
function health(){const modulesMap=state.manifest?.modules||Object.fromEntries((state.manifest?.sources||[]).map(item=>[item.module,item]));$('#health').innerHTML=table(['模块','状态','记录数','最后成功','异常'],Object.entries(modulesMap).filter(([name])=>modules[name]).map(([name,item])=>[esc(modules[name].title),`<span class="status ${esc(item.status)}">${esc(item.status)}</span>`,num(item.rows),esc(item.last_success_at_utc?.replace('T',' ').slice(0,19)||item.snapshot_date||'—'),esc(item.error||'')]));const terms=state.manifest?.terms||{};$('#terms').innerHTML=Object.entries(terms).map(([term,note])=>`<dt>${esc(term)}</dt><dd>${esc(note)}</dd>`).join('');}
async function boot(){const params=new URLSearchParams(location.search);state.query=params.get('q')||'';state.filter=params.get('filter')||'all';try{await loadManifest();health();}catch(error){setStatus('数据清单读取失败：'+error.message,'warning');}const requested=location.hash.slice(1);if(requested==='github-trending'){state.module='github';state.githubView='trending';updateUrl();}else state.module=modules[requested]?requested:'overview';renderCurrent();}
const nav=document.querySelector('nav[aria-label="看板栏目"]');
[['ai-financials','上市公司Capex','08'],['ai-frontier','AI 研究前沿与模型能力','09']].forEach(([name,label,index])=>{if(nav&&!nav.querySelector(`[data-module="${name}"]`)){const button=document.createElement('button');button.dataset.module=name;button.innerHTML=`${esc(label)} <span>${index}</span>`;nav.append(button);}});
document.querySelectorAll('[data-module]').forEach(button=>button.addEventListener('click',()=>{state.module=button.dataset.module;if(state.module==='github')state.githubView='trending';state.query='';state.filter='all';state.selected=null;state.dataView='summary';state.xPriority=false;state.xCategory='all';state.xAccount='all';updateUrl();renderCurrent();}));
window.addEventListener('hashchange',()=>{const name=location.hash.slice(1);if(modules[name]&&name!==state.module){state.module=name;state.dataView='summary';renderCurrent();}});
$('#refresh').addEventListener('click',async()=>{$('#refresh').disabled=true;try{await loadManifest(true);if(state.module!=='overview')await loadModule(state.module==='github'&&state.githubView==='trending'?'github-trending':state.module,true);health();renderCurrent();}finally{$('#refresh').disabled=false;}});
$('#show-health').addEventListener('click',()=>{$('#health-panel').hidden=false;$('#health-panel').scrollIntoView({behavior:'smooth'});});$('#close-health').addEventListener('click',()=>$('#health-panel').hidden=true);$('#close-drawer').addEventListener('click',()=>$('#drawer').close());
try{document.body.classList.toggle('dark',localStorage.getItem('ai-theme')==='dark');}catch{}
$('#theme').addEventListener('click',()=>{document.body.classList.toggle('dark');try{localStorage.setItem('ai-theme',document.body.classList.contains('dark')?'dark':'light');}catch{}});
const chartTooltip=document.createElement('div');
chartTooltip.className='chart-tooltip';
chartTooltip.setAttribute('role','status');
chartTooltip.setAttribute('aria-live','off');
document.body.append(chartTooltip);
let tipNode=null,tipFrame=0;
function positionChartTooltip(x,y){
  cancelAnimationFrame(tipFrame);
  tipFrame=requestAnimationFrame(()=>{
    const width=chartTooltip.offsetWidth,height=chartTooltip.offsetHeight;
    chartTooltip.style.left=`${Math.max(12,Math.min(innerWidth-width-12,x+16))}px`;
    chartTooltip.style.top=`${Math.max(12,Math.min(innerHeight-height-12,y+16))}px`;
  });
}
function showChartTooltip(node,x,y){
  if(tipNode!==node){
    tipNode=node;
    chartTooltip.replaceChildren();
    const name=document.createElement('div'),swatch=document.createElement('i'),text=document.createElement('span'),value=document.createElement('div');
    name.className='tooltip-name';swatch.className='tooltip-swatch';value.className='tooltip-value';
    swatch.style.backgroundColor=node.dataset.tipColor||'#1683e8';
    text.textContent=node.dataset.tipName||'';
    value.textContent=node.dataset.tipValue||'';
    name.append(swatch,text);chartTooltip.append(name,value);
  }
  chartTooltip.classList.add('is-visible');
  positionChartTooltip(x,y);
}
function hideChartTooltip(){tipNode=null;chartTooltip.classList.remove('is-visible');}
document.addEventListener('pointermove',event=>{
  const node=event.target.closest?.('[data-trend-tip]');
  if(node)showChartTooltip(node,event.clientX,event.clientY);
  else hideChartTooltip();
});
document.addEventListener('focusin',event=>{
  const node=event.target.closest?.('[data-trend-tip]');
  if(node){const rect=node.getBoundingClientRect();showChartTooltip(node,rect.right,rect.top);}
});
document.addEventListener('focusout',event=>{if(event.target.closest?.('[data-trend-tip]'))hideChartTooltip();});
document.addEventListener('keydown',event=>{if(event.key==='Escape')hideChartTooltip();});
boot();
